<?php
namespace Azuriom\Plugin\GamingHubCore\Services;
use Azuriom\Plugin\GamingHubCore\Contracts\PublicDataPolicyResolver; use Azuriom\Plugin\GamingHubCore\Data\PublicStatisticPolicy; use Azuriom\Plugin\GamingHubCore\Models\PublicDataPolicy; use Azuriom\Plugin\GamingHubCore\Models\Server; use Azuriom\Plugin\GamingHubCore\Settings\PublicDataSettings;
final class DefaultPublicDataPolicyResolver implements PublicDataPolicyResolver { public function __construct(private PublicDataSettings $settings){} public function effective(?Server $server,string $key):PublicStatisticPolicy{$g=$this->settings->global($key);if(!$server)return new PublicStatisticPolicy($key,$g['visible'],$g['attribution']);$o=PublicDataPolicy::query()->where('server_id',$server->id)->where('stat_key',$key)->first();$visible=$o&&$o->visibility!=='inherit'?$o->visibility==='show':$g['visible'];$attr=$o&&$o->attribution!=='inherit'?$o->attribution==='show':$g['attribution'];return new PublicStatisticPolicy($key,$visible,$attr);} public function filter(Server $server,array $data,?string $sourceLabel=null):array{$out=[];$source=false;foreach($data as $k=>$v){if(!NormalizedDataKeys::valid((string)$k))continue;$p=$this->effective($server,(string)$k);if($p->visible){$out[$k]=$v;$source=$source||$p->attribution;}}return ['data'=>$out,'source'=>$source?($sourceLabel?:'Provider'):null];} }
